pub const FR:Lang=Lang{ name:"Lampe Aurora Prisme — édition signature", tagline:"Verre soufflé à la main, laiton massif, lumière spectrale réglable.", desc:"Chaque Aurora Prisme est soufflée à la main puis polie pendant douze heures. Son diffuseur décompose la lumière en un spectre doux qui transforme un salon en galerie. Livrée dans un coffret numéroté avec certificat d'authenticité.", specs:&[("Matériaux","Verre borosilicaté, laiton massif"),("Dimensions","32 × 32 × 48 cm"),("Poids","4,2 kg"),("Source","LED 2700–6500 K, 1 200 lm"),("Garantie","3 ans, pièces et main-d'œuvre"),("Livraison","58 wilayas, paiement à la livraison")], lang:"fr", dir:"ltr", currency:"DA", price_label:"Prix", order:"Commander — paiement à la livraison", f_name:"Nom complet", phone:"Téléphone", wilaya:"Wilaya", commune:"Commune", choose:"Choisir la wilaya", specs_t:"Caractéristiques", submit:"Confirmer la commande", note:"Notre équipe vous appelle pour confirmer avant l'expédition. Vous payez à la réception.", phone_hint:"Format : 05, 06 ou 07 suivi de 8 chiffres", home:"Accueil", cat:"Luminaires", other:"العربية", other_href:"/ar/", title:"Lampe Aurora Prisme | Maison Lumen" };
